# invoice_totals.py - used by the monthly billing run
from decimal import Decimal, ROUND_HALF_UP

VAT_RATES = {"standard": Decimal("0.21"), "reduced": Decimal("0.09")}

def line_total(quantity: int, unit_price: Decimal, rate: str = "standard") -> Decimal:
    """Return the gross amount for one invoice line, rounded to cents."""
    net = quantity * unit_price
    gross = net * (1 + VAT_RATES[rate])
    return gross.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

# {{INSERT}}

def invoice_total(lines) -> Decimal:
    # lines is a list of (quantity, unit_price, rate) tuples
    return sum((line_total(*line) for line in lines), Decimal("0"))

// debounce.ts - small helper shared by the search box and the address form
export function debounce<T extends (...args: any[]) => void>(fn: T, waitMs = 250) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return (...args: Parameters<T>) => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => fn(...args), waitMs);
  };
}

