use std::collections::HashMap;

/// Count how often each word appears in a customer review.
/// Words are lowercased and punctuation at the edges is trimmed.
pub fn word_counts(text: &str) -> HashMap<String, usize> {
    let mut counts = HashMap::new();
    for raw in text.split_whitespace() {
        let word = raw.trim_matches(|c: char| !c.is_alphanumeric()).to_lowercase();
        if word.is_empty() {
            continue;
        }
        // {{INSERT}}
        *counts.entry(word).or_insert(0) += 1;
    }
    counts
}

public class ShippingCalculator {

    private static final double FREE_SHIPPING_THRESHOLD = 50.00;
    private static final double BASE_RATE = 4.95;

    /** Returns the shipping cost in euros for a basket total and weight in kilograms. */
    public double costFor(double basketTotal, double weightKg) {
        if (basketTotal >= FREE_SHIPPING_THRESHOLD) {
            return 0.0;
        }
        // {{INSERT}}
        double surcharge = weightKg > 10 ? 3.50 : 0.0;
        return BASE_RATE + surcharge;
    }
}

