# openingstijden.py - bepaalt of de winkel nu open is
from datetime import datetime, time

OPENINGSTIJDEN = {
    0: (time(9, 0), time(18, 0)),   # maandag
    4: (time(9, 0), time(21, 0)),   # vrijdag koopavond
    5: (time(10, 0), time(17, 0)),  # zaterdag
}

def is_open(moment: datetime) -> bool:
    """Geeft True terug als de winkel op dit moment open is."""
    tijden = OPENINGSTIJDEN.get(moment.weekday())
    # {{INSERT}}
    if tijden is None:
        return False  # op zondag zijn we gesloten
    return tijden[0] <= moment.time() < tijden[1]

