# contributie.py - berekent de jaarlijkse contributie van de tennisvereniging
BASIS = 185.00
JEUGDKORTING = 0.50   # leden onder de 18 betalen de helft
GEZINSKORTING = 25.00 # vanaf het derde gezinslid

def contributie(leeftijd: int, gezinslid_nummer: int = 1) -> float:
    bedrag = BASIS
    if leeftijd < 18:
        bedrag *= JEUGDKORTING
    # {{INSERT}}
    if gezinslid_nummer >= 3:
        bedrag -= GEZINSKORTING
    return round(bedrag, 2)

