# mahnung.py - erzeugt den Text für die erste Zahlungserinnerung
from datetime import date, timedelta

ZAHLUNGSFRIST_TAGE = 14

def mahntext(kunde: str, rechnungsnummer: str, betrag: float) -> str:
    """Gibt den Text der Zahlungserinnerung zurück."""
    frist = date.today() + timedelta(days=ZAHLUNGSFRIST_TAGE)
    # {{INSERT}}
    return (
        f"Sehr geehrte(r) {kunde},\n"
        f"die Rechnung {rechnungsnummer} über {betrag:.2f} Euro ist noch offen.\n"
        f"Bitte überweisen Sie den Betrag bis zum {frist:%d.%m.%Y}."
    )

// Lagerbestand.java - prüft, ob ein Artikel nachbestellt werden muss
public class Lagerbestand {

    private final int mindestmenge;
    private int menge;

    public Lagerbestand(int menge, int mindestmenge) {
        this.menge = menge;
        this.mindestmenge = mindestmenge;
    }

    // {{INSERT}}

    /** Liefert true, wenn der Bestand unter die Mindestmenge gefallen ist. */
    public boolean nachbestellenNoetig() {
        return menge < mindestmenge;
    }

    public void entnehmen(int anzahl) {
        // negative Bestände sind nicht erlaubt
        menge = Math.max(0, menge - anzahl);
    }
}

# remise.py - calcule la remise fidélité de la librairie
SEUIL_FIDELITE = 10      # nombre d'achats avant la première remise
TAUX_REMISE = 0.05       # cinq pour cent

def prix_final(prix: float, nombre_achats: int) -> float:
    """Renvoie le prix après application éventuelle de la remise."""
    # {{INSERT}}
    if nombre_achats >= SEUIL_FIDELITE:
        prix = prix * (1 - TAUX_REMISE)
    # le prix du livre ne peut pas baisser de plus de 5 % en France
    return round(prix, 2)

