# propina.py - reparte la propina entre el personal del restaurante
def repartir_propina(total: float, horas_por_persona: dict) -> dict:
    """Devuelve cuánto le corresponde a cada persona según las horas trabajadas."""
    horas_totales = sum(horas_por_persona.values())
    reparto = {}
    # {{INSERT}}
    for nombre, horas in horas_por_persona.items():
        reparto[nombre] = round(total * horas / horas_totales, 2)
    return reparto

# Ejemplo: 120 euros entre Carmen (8 h), Julián (6 h) y Nerea (6 h)
