// calendario.ts - calcula los días que faltan para la próxima cita
export function diasHastaCita(fechaCita: Date, hoy: Date = new Date()): number {
  const milisegundosPorDia = 24 * 60 * 60 * 1000;
  const diferencia = fechaCita.getTime() - hoy.getTime();

  // {{INSERT}}

  // redondeamos hacia arriba para que una cita de mañana cuente como 1 día
  return Math.max(0, Math.ceil(diferencia / milisegundosPorDia));
}

