# frete.py - calcula o frete para as encomendas da loja de cerâmica
FRETE_GRATIS_ACIMA_DE = 60.0
TARIFA_BASE = 4.50
TARIFA_ILHAS = 9.90

def calcular_frete(total: float, regiao: str) -> float:
    """Devolve o valor do frete em euros."""
    if total >= FRETE_GRATIS_ACIMA_DE:
        return 0.0
    # {{INSERT}}
    if regiao in ("Açores", "Madeira"):
        return TARIFA_ILHAS  # envio para as ilhas é mais caro
    return TARIFA_BASE

