# zaiko.py - 在庫が少なくなった商品を一覧にする
SAITEI_ZAIKO = 5  # この数を下回ったら発注する

def hacchu_list(zaiko: dict) -> list:
    """在庫数が基準を下回っている商品名のリストを返す。"""
    kekka = []
    # {{INSERT}}
    for shohin, kazu in zaiko.items():
        if kazu < SAITEI_ZAIKO:
            kekka.append(shohin)  # 発注が必要な商品
    return sorted(kekka)

# 例: 抹茶ラテの粉が残り3袋なら、発注リストに追加される
